/**
 * @title Analytics overview with tabs
 * @description A header-only layout: top navigation, a date-range action, tabs for Overview / Analytics / Reports, key numbers, monthly revenue and recent sales.
 * @route /dashboard
 * @height 900
 */
import { TopBar } from "@/components/top-bar";
import { Overview } from "@/components/overview";

export default function Page() {
  return (
    <div className="flex min-h-svh flex-col bg-canvas">
      <TopBar current="Overview" />
      <main id="main" className="mx-auto flex w-full max-w-7xl flex-1 flex-col gap-6 px-4 py-6 md:px-6">
        <Overview />
      </main>
    </div>
  );
}

"use client";
import { Gauge } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";

const links = ["Overview", "Customers", "Products", "Settings"];

/** A header-only app layout: logo, top navigation and the account menu. */
export function TopBar({ current = "Overview" }: { current?: string }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] border-b border-line-default bg-surface">
      <div className="mx-auto flex h-14 max-w-7xl items-center gap-6 px-4 md:px-6">
        <a href="#" className="flex items-center gap-2 rounded-sm text-label-large focus-visible:focus-ring">
          <span className="grid size-7 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={Gauge} size={16} /></span>
          Acme
        </a>
        <nav aria-label="Main" className="max-md:hidden">
          <ul className="flex items-center gap-1">
            {links.map((l) => (
              <li key={l}>
                <a href="#" aria-current={l === current ? "page" : undefined}
                  className="flex h-8 items-center rounded-control px-3 text-label-medium text-fg-secondary hover:bg-neutral-hover hover:text-fg-primary focus-visible:focus-ring aria-[current=page]:text-fg-primary">
                  {l}
                </a>
              </li>
            ))}
          </ul>
        </nav>
        <div className="ms-auto">
          <Menu
            label="Account menu for Jane Cooper"
            items={[{ label: "Profile", icon: "user" }, { label: "Settings", icon: "settings" }, { label: "Sign out", icon: "sign-out", separatorBefore: true }]}
            trigger={({ ref, ...p }) => (
              <button ref={ref} type="button" {...p} aria-label="Account menu for Jane Cooper" className="rounded-full focus-visible:focus-ring">
                <Avatar name="Jane Cooper" decorative />
              </button>
            )}
          />
        </div>
      </div>
    </header>
  );
}

"use client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Avatar, StatCard } from "@/components/ui/display";
import { Tabs } from "@/components/ui/navigation";
import { BarChart } from "@/components/bar-chart";

const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const revenue = months.map((label, i) => ({ label, value: 1800 + ((i * 2731) % 4200) }));
const sales = [
  { name: "Olivia Martin", email: "olivia.martin@email.com", amount: "+$1,999.00" },
  { name: "Jackson Lee", email: "jackson.lee@email.com", amount: "+$39.00" },
  { name: "Isabella Nguyen", email: "isabella.nguyen@email.com", amount: "+$299.00" },
  { name: "William Kim", email: "will@email.com", amount: "+$99.00" },
  { name: "Sofia Davis", email: "sofia.davis@email.com", amount: "+$39.00" },
];

function OverviewPanel() {
  return (
    <div className="flex flex-col gap-4">
      <section aria-label="Key numbers" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Total revenue" value="$45,231.89" trend={{ direction: "positive", value: "+20.1%" }} context="from last month" />
        <StatCard label="Subscriptions" value="+2,350" trend={{ direction: "positive", value: "+180.1%" }} context="from last month" />
        <StatCard label="Sales" value="+12,234" trend={{ direction: "positive", value: "+19%" }} context="from last month" />
        <StatCard label="Active now" value="+573" trend={{ direction: "neutral", value: "+201" }} context="since last hour" />
      </section>
      <div className="grid gap-4 lg:grid-cols-7">
        <section aria-labelledby="rev-title" className="flex min-w-0 flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)] lg:col-span-4">
          <h2 id="rev-title" className="text-heading-h4">Revenue by month</h2>
          <BarChart title="Revenue by month, 2026, in US dollars" data={revenue} format={(n) => `$${n.toLocaleString("en-US")}`} />
        </section>
        <section aria-labelledby="sales-title" className="flex min-w-0 flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)] lg:col-span-3">
          <div className="flex flex-col gap-1">
            <h2 id="sales-title" className="text-heading-h4">Recent sales</h2>
            <p className="text-body-small text-fg-secondary">You made 265 sales this month.</p>
          </div>
          <ul className="flex flex-col gap-5">
            {sales.map((s) => (
              <li key={s.email} className="flex items-center gap-3">
                <Avatar name={s.name} size="lg" decorative />
                <span className="flex min-w-0 flex-1 flex-col"><span className="truncate text-label-medium">{s.name}</span><span className="truncate text-caption-default text-fg-secondary">{s.email}</span></span>
                <span className="text-label-medium tabular-nums">{s.amount}</span>
              </li>
            ))}
          </ul>
        </section>
      </div>
    </div>
  );
}

const soon = (what: string) => <p className="rounded-container border border-dashed border-line-strong p-10 text-center text-body-small text-fg-secondary">{what} go here.</p>;

export function Overview() {
  const [tab, setTab] = useState("overview");
  return (
    <>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-heading-h2">Dashboard</h1>
        <div className="flex gap-2"><Button variant="secondary" leadingIcon="calendar">Jan 20 – Feb 9, 2026</Button><Button leadingIcon="download">Download</Button></div>
      </div>
      <Tabs label="Dashboard views" value={tab} onChange={setTab}
        tabs={[
          { id: "overview", label: "Overview", panel: <OverviewPanel /> },
          { id: "analytics", label: "Analytics", panel: soon("Analytics") },
          { id: "reports", label: "Reports", count: 3, panel: soon("Reports") },
        ]} />
    </>
  );
}

/** A vertical bar chart in HTML/CSS with DX data-viz colours. Screen readers get the numbers as a table. */
export function BarChart({ title, data, height = 220, format = (n: number) => n.toLocaleString("en-US") }: {
  title: string;
  data: { label: string; value: number }[];
  height?: number;
  format?: (n: number) => string;
}) {
  const max = Math.max(...data.map((d) => d.value)) || 1;
  return (
    <figure className="flex flex-col gap-2">
      <figcaption className="sr-only">{title}</figcaption>
      <div aria-hidden className="flex items-end gap-1 border-b sm:gap-2 border-line-default" style={{ height }}>
        {data.map((d) => (
          <div key={d.label} className="group relative flex h-full min-w-0 flex-1 flex-col justify-end">
            <span className="pointer-events-none absolute inset-x-0 -top-0 text-center text-caption-default text-fg-secondary opacity-0 tabular-nums group-hover:opacity-100">{format(d.value)}</span>
            <div className="rounded-t-sm bg-[var(--ds-color-dataviz-series-1)] transition-opacity group-hover:opacity-80" style={{ height: `${(d.value / max) * 90}%` }} />
          </div>
        ))}
      </div>
      <div aria-hidden className="flex gap-1 text-caption-default sm:gap-2 text-fg-secondary">
        {data.map((d) => <span key={d.label} className="min-w-0 flex-1 truncate text-center">{d.label}</span>)}
      </div>
      <table className="sr-only">
        <caption>{title}</caption>
        <tbody>{data.map((d) => <tr key={d.label}><th scope="row">{d.label}</th><td>{format(d.value)}</td></tr>)}</tbody>
      </table>
    </figure>
  );
}
